import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"48、【井】 巽下坎上","description":"橫渠易說 - 48、【井】 巽下坎上","frontmatter":{"title":"48、【井】 巽下坎上","description":"橫渠易說 - 48、【井】 巽下坎上"},"headers":[],"relativePath":"classics/hengqu/050.md","filePath":"classics/hengqu/050.md"}'),l={name:"classics/hengqu/050.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_48、【井】-巽下坎上" tabindex="-1">48、【井】 巽下坎上 <a class="header-anchor" href="#_48、【井】-巽下坎上" aria-label="Permalink to “48、【井】 巽下坎上”">​</a></h1><h3 id="彖曰-巽乎水而上水-井。井-養而不窮也-改邑不改井-乃以剛中也-汔至亦未繘井-未有功也-贏其瓶-是以兇也。" tabindex="-1">彖曰：巽乎水而上水，井。井，養而不窮也；“改邑不改井”，乃以剛中也；“汔至亦未繘井”，未有功也，“贏其瓶”，是以兇也。 <a class="header-anchor" href="#彖曰-巽乎水而上水-井。井-養而不窮也-改邑不改井-乃以剛中也-汔至亦未繘井-未有功也-贏其瓶-是以兇也。" aria-label="Permalink to “彖曰：巽乎水而上水，井。井，養而不窮也；“改邑不改井”，乃以剛中也；“汔至亦未繘井”，未有功也，“贏其瓶”，是以兇也。”">​</a></h3><h3 id="象曰-木上有水-井-君子以勞民勸相。" tabindex="-1">象曰：木上有水，井，君子以勞民勸相。 <a class="header-anchor" href="#象曰-木上有水-井-君子以勞民勸相。" aria-label="Permalink to “象曰：木上有水，井，君子以勞民勸相。”">​</a></h3><p>養而不窮，莫若勞民而勸相也。</p><h3 id="初六-井泥不食-舊井無禽。-象曰-井泥不食-下也-舊井無禽-時舍也。" tabindex="-1">初六，井泥不食，舊井無禽。 象曰：“井泥不食”，下也；“舊井無禽”，時舍也。 <a class="header-anchor" href="#初六-井泥不食-舊井無禽。-象曰-井泥不食-下也-舊井無禽-時舍也。" aria-label="Permalink to “初六，井泥不食，舊井無禽。 象曰：“井泥不食”，下也；“舊井無禽”，時舍也。”">​</a></h3><h3 id="九二-井谷射鮒-甕敝漏。-象曰-井谷射鮒-無與也。" tabindex="-1">九二，井谷射鮒，甕敝漏。 象曰：“井谷射鮒”，無與也。 <a class="header-anchor" href="#九二-井谷射鮒-甕敝漏。-象曰-井谷射鮒-無與也。" aria-label="Permalink to “九二，井谷射鮒，甕敝漏。 象曰：“井谷射鮒”，無與也。”">​</a></h3><h3 id="九三-井渫不食-為我心惻-可用汲。王明並受其福。-象曰-井渫不食-行惻也-求王明-受福也。" tabindex="-1">九三，井渫不食，為我心惻，可用汲。王明並受其福。 象曰：“井渫不食”，行惻也；求王明，受福也。 <a class="header-anchor" href="#九三-井渫不食-為我心惻-可用汲。王明並受其福。-象曰-井渫不食-行惻也-求王明-受福也。" aria-label="Permalink to “九三，井渫不食，為我心惻，可用汲。王明並受其福。 象曰：“井渫不食”，行惻也；求王明，受福也。”">​</a></h3><p>井以既出為功，井道之成在於上六，三其正應，而又以陽居陽，充滿可汲，為五所間，功不上施，故為我心惻。然若上六明於照物，則上下遠邇皆獲其利。“井渫不食”，強施行惻，然且不售，作易者之嘆歟!</p><h3 id="六四-井甃-無咎。-象曰-井甃無咎-修井也。" tabindex="-1">六四，井甃，無咎。 象曰：“井甃無咎”，修井也。 <a class="header-anchor" href="#六四-井甃-無咎。-象曰-井甃無咎-修井也。" aria-label="Permalink to “六四，井甃，無咎。 象曰：“井甃無咎”，修井也。”">​</a></h3><p>無應於上，無敝漏於下，故但免咎而已。</p><h3 id="九五-井冽寒泉食。-象曰-寒泉之食-中正也。-井冽寒泉-美而可汲者也-剛中之德為眾所利。" tabindex="-1">九五，井冽寒泉食。 象曰：寒泉之食，中正也。“井冽寒泉”，美而可汲者也，剛中之德為眾所利。 <a class="header-anchor" href="#九五-井冽寒泉食。-象曰-寒泉之食-中正也。-井冽寒泉-美而可汲者也-剛中之德為眾所利。" aria-label="Permalink to “九五，井冽寒泉食。 象曰：寒泉之食，中正也。“井冽寒泉”，美而可汲者也，剛中之德為眾所利。”">​</a></h3><h3 id="上六-井收勿幕-有孚元吉。-象曰-元吉在上-大成也。" tabindex="-1">上六，井收勿幕，有孚元吉。 象曰：元吉在上，大成也。 <a class="header-anchor" href="#上六-井收勿幕-有孚元吉。-象曰-元吉在上-大成也。" aria-label="Permalink to “上六，井收勿幕，有孚元吉。 象曰：元吉在上，大成也。”">​</a></h3>',12)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
